package secondweek;

public class Assgn4 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		for(int i=1 ; i<=10 ; i++) {
			if(i%2==0)
		{
			System.out.println( i + " is Even Number ");
		}
			else
			{
				System.out.println( i + " is  Odd Number ");
			}
		}
	}

}
